"""UnaryOpType.QUICK_GELU: ttnn.unary_chain of the one op runs quick_gelu's generated SFPU kernel."""

import pytest
import torch
import ttnn
from models.common.utility_functions import is_blackhole


# Generated by tt-polynomial-fitter for quick_gelu; do not edit below this line.
# Certified within 0.976 ULP of the exact result over every finite BF16 input.

_GENERATED_QUICK_GELU_CLASSES = {
    "+0": 0.0,
    "-0": -0.0,
    "+inf": float("inf"),
    "-inf": -float("inf"),
    "nan": float("nan"),
    "+1": 1.0,
    "-1": -1.0,
    "-100": -100.0,
    "+200": 200.0,
}
# Input class -> the result's class: torch's, except where the stock path and torch differ (signed zero, subnormal
# inputs read as zero) and the kernel keeps the stock one.
_GENERATED_QUICK_GELU_SPECIAL_RESULTS = {
    "+0": "+0",
    "+1": "finite",
    "+200": "finite",
    "+inf": "+inf",
    "-0": "+0",  # torch gives -0; this kernel stores +0
    "-1": "finite",
    "-100": "+0",  # torch gives -0; this kernel stores +0
    "-inf": "nan",  # NaN, as torch gives; the BF16 pack stores a NaN as +inf, which the device reads back
    "nan": "nan",  # NaN, as torch gives; the BF16 pack stores a NaN as +inf, which the device reads back
}
_GENERATED_QUICK_GELU_TINY = torch.finfo(torch.float32).tiny  # 2^-126, the smallest normal
_GENERATED_QUICK_GELU_BF16_MAX = torch.finfo(torch.bfloat16).max
# Results the kernel may store as 0: within this relative distance above the smallest normal, and at every input at or
# below the next, where the exp leaf's e^-|z| is 0.
_GENERATED_QUICK_GELU_BOUNDARY_BAND = 2.0**-12
_GENERATED_QUICK_GELU_LOGISTIC_FLUSH_INPUT = -51.5


def _generated_quick_gelu_run(device, values):
    """ttnn.unary_chain(x, [ttnn.UnaryWithParam(ttnn.UnaryOpType.QUICK_GELU)]) of a 1-D BF16 tensor x, padded with ones to whole 32x32 tiles."""
    n = values.numel()
    padded = torch.cat([values, torch.ones((-n) % (32 * 32), dtype=values.dtype)])
    tensor = ttnn.from_torch(padded.reshape(1, 1, -1, 32), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device)
    return ttnn.to_torch(ttnn.unary_chain(tensor, [ttnn.UnaryWithParam(ttnn.UnaryOpType.QUICK_GELU)])).reshape(-1)[:n]


def _generated_quick_gelu_assert(inputs, actual):
    """The generated kernel's BF16 outputs ``actual`` for BF16 ``inputs``: below 1 pure ULP of the exact result of the
    input as the SFPU reads it (a subnormal as 0, as stock does). The exact result is the formula in float64, which
    has no cancellation here. A lane the kernel stores as 0 where the logistic factor underflows, or whose exact
    result lies in the band just above the smallest normal, is not scored; a result below the smallest normal is
    0 or the smallest normal it rounds to."""
    tiny = _GENERATED_QUICK_GELU_TINY
    x = inputs.to(torch.float64)
    actual = actual.to(torch.float64)
    x = torch.where(x.abs() < tiny, torch.zeros_like(x), x)
    exact = x / (1 + torch.exp(-1.702 * x))
    normal = (exact.abs() >= tiny) & (exact.abs() <= _GENERATED_QUICK_GELU_BF16_MAX)
    ulp = torch.exp2(torch.floor(torch.log2(exact.abs().clamp(min=tiny))) - 7)  # a BF16 step: 7 stored mantissa bits
    edge = exact.abs() < tiny * (1 + _GENERATED_QUICK_GELU_BOUNDARY_BAND)
    flushed = normal & (actual == 0) & ((x <= _GENERATED_QUICK_GELU_LOGISTIC_FLUSH_INPUT) | edge)
    scored = ((actual - exact).abs() / ulp)[normal & ~flushed]
    worst, over = scored.max().item(), int((scored >= 1.0).sum())
    assert worst < 1.0, f"max {worst:.4f} pure ULP; {over} of {scored.numel()} scored lanes at or above 1"
    below = ~normal & (exact.abs() < tiny)
    raised = int((actual[below].abs() > tiny).sum())
    assert raised == 0, f"{raised} of {int(below.sum())} results below the smallest normal are stored above it"


@pytest.mark.skipif(
    not is_blackhole(),
    reason="quick_gelu's generated SFPU kernel is certified on Blackhole only; Wormhole keeps the stock body",
)
def test_quick_gelu_sfpu_generated_bf16_sweep(device):
    """Every finite BF16 encoding, scored as the certificate scores it."""
    bits = torch.arange(65536, dtype=torch.int32)
    every = (bits << 16).view(torch.float32)
    every = every[torch.isfinite(every)].to(torch.bfloat16)
    _generated_quick_gelu_assert(every, _generated_quick_gelu_run(device, every))


@pytest.mark.skipif(
    not is_blackhole(),
    reason="quick_gelu's generated SFPU kernel is certified on Blackhole only; Wormhole keeps the stock body",
)
def test_quick_gelu_sfpu_generated_specials(device):
    """NaN gives NaN (stored as +inf); the other classes as torch, or as the stock path where the two differ."""
    names = list(_GENERATED_QUICK_GELU_SPECIAL_RESULTS)
    values = torch.tensor([_GENERATED_QUICK_GELU_CLASSES[key] for key in names], dtype=torch.float32)
    actual = _generated_quick_gelu_run(device, values.to(torch.bfloat16)).to(torch.float32)

    def kind(v):
        if torch.isnan(v):
            return "nan"
        if torch.isinf(v):
            return "+inf" if v > 0 else "-inf"
        if v == 0:
            return "-0" if torch.signbit(v) else "+0"
        return "finite"

    # The BF16 pack stores a NaN as +inf.
    stored = {"nan": "+inf"}
    got = {key: kind(actual[i]) for i, key in enumerate(names)}
    want = {key: stored.get(cls, cls) for key, cls in _GENERATED_QUICK_GELU_SPECIAL_RESULTS.items()}
    assert got == want


@pytest.mark.parametrize("case", ["float32_input", "chained", "other_board"])
def test_quick_gelu_op_type_refuses_the_calls_its_kernel_does_not_serve(device, case, expect_error):
    """QUICK_GELU has no kernel but the generated one: a FLOAT32 input, a chain with another op, or a board without the
    kernel raises instead of building nothing."""
    if (case == "other_board") == is_blackhole():
        pytest.skip("the case is for the other board")
    dtype = ttnn.float32 if case == "float32_input" else ttnn.bfloat16
    tensor = ttnn.from_torch(torch.ones((1, 1, 32, 32)), dtype=dtype, layout=ttnn.TILE_LAYOUT, device=device)
    chain = [ttnn.UnaryWithParam(ttnn.UnaryOpType.QUICK_GELU)]
    if case == "chained":
        chain.append(ttnn.UnaryWithParam(ttnn.UnaryOpType.RELU))
    with expect_error(RuntimeError, "QUICK_GELU runs only"):
        ttnn.unary_chain(tensor, chain)
